import copy
import os
import sys
import unittest
from unittest.mock import patch

sys.path.insert(0, os.getcwd())

from src.csv_exporter import export_csv
from src.dispatcher import export
from src.exporter import export_rows
from src.json_exporter import export_json


class OneShotRows:
    def __init__(self, rows):
        self.rows = rows
        self.consumed = False

    def __iter__(self):
        if self.consumed:
            raise AssertionError("rows iterated more than once")
        self.consumed = True
        return iter(self.rows)


class ExporterTests(unittest.TestCase):
    def test_exact_output_and_input_preservation(self):
        rows = [
            {"id": 1, "name": 'Zoë, "雪"\nnext', "ignored": object()},
            {"name": None},
            {"id": False, "name": 0},
            {"id": None},
        ]
        original = [row.copy() for row in rows]
        expected = {
            "csv": 'id,name\n1,"Zoë, ""雪""\nnext"\n,\nFalse,0\n,\n',
            "json": '[{"id":"1","name":"Zoë, \\"雪\\"\\nnext"},'
                    '{"id":"","name":""},{"id":"False","name":"0"},'
                    '{"id":"","name":""}]',
        }
        for format, wrapper in (("csv", export_csv), ("json", export_json)):
            for entry_point in (export_rows, export):
                with self.subTest(format=format, entry_point=entry_point):
                    self.assertEqual(entry_point(OneShotRows(rows), format), expected[format])
            self.assertEqual(wrapper(OneShotRows(rows)), expected[format])
        self.assertEqual(rows, original)

    def test_empty_rows(self):
        for format, expected in (("csv", "id,name\n"), ("json", "[]")):
            self.assertEqual(export_rows(iter(()), format), expected)
            self.assertEqual(export([], format), expected)

    def test_nested_values_are_stringified_without_mutation(self):
        rows = [{"id": [1, 2], "name": {"a": 1}, "other": [3]}]
        original = copy.deepcopy(rows)
        self.assertEqual(export_csv(rows), 'id,name\n"[1, 2]",{\'a\': 1}\n')
        self.assertEqual(export_json(rows), '[{"id":"[1, 2]","name":"{\'a\': 1}"}]')
        self.assertEqual(rows, original)

    def test_unsupported_format_does_not_consume_rows(self):
        rows = OneShotRows([])
        for entry_point in (export_rows, export):
            with self.assertRaisesRegex(ValueError, "^unsupported format$"):
                entry_point(rows, "xml")
        self.assertFalse(rows.consumed)

    def test_wrappers_delegate(self):
        rows = iter(())
        for module, wrapper, format in (
            ("src.csv_exporter", export_csv, "csv"),
            ("src.json_exporter", export_json, "json"),
        ):
            with patch(module + ".export_rows", return_value="result") as shared:
                self.assertEqual(wrapper(rows), "result")
                shared.assert_called_once_with(rows, format)


if __name__ == "__main__":
    unittest.main()

